"use client";

import { useMemo, useState } from "react";

import { SidebarInset, SidebarProvider } from "@/components/ui/sidebar";
import { hubs, routes, type Filter } from "./data";
import { FilterSidebar } from "./components/filter-sidebar";
import { NetworkMap } from "./components/network-map";

export default function Page() {
  const [hidden, setHidden] = useState<Set<Filter>>(new Set());

  function toggle(filter: Filter) {
    setHidden((current) => {
      const next = new Set(current);
      if (next.has(filter)) next.delete(filter);
      else next.add(filter);
      return next;
    });
  }

  const visibleHubs = useMemo(
    () => hubs.filter((hub) => !hidden.has(hub.region)),
    [hidden],
  );
  const visibleRoutes = useMemo(() => {
    const visibleHubIds = new Set(visibleHubs.map((hub) => hub.id));
    return routes.filter(
      (route) =>
        !hidden.has(route.mode) &&
        !hidden.has(route.status) &&
        visibleHubIds.has(route.from) &&
        visibleHubIds.has(route.to),
    );
  }, [hidden, visibleHubs]);

  return (
    <SidebarProvider>
      <FilterSidebar
        hubs={hubs}
        routes={routes}
        visibleRoutes={visibleRoutes}
        hidden={hidden}
        onToggle={toggle}
      />
      <SidebarInset>
        <NetworkMap hubs={visibleHubs} routes={visibleRoutes} />
      </SidebarInset>
    </SidebarProvider>
  );
}

"use client";

import {
  Sidebar,
  SidebarContent,
  SidebarGroup,
  SidebarGroupContent,
  SidebarGroupLabel,
  SidebarHeader,
  SidebarMenu,
  SidebarMenuBadge,
  SidebarMenuButton,
  SidebarMenuItem,
  SidebarSeparator,
} from "@/components/ui/sidebar";
import { MapPin, Network, Plane, Truck } from "lucide-react";
import { cn } from "@/lib/utils";
import {
  regionLabels,
  statusConfig,
  type Filter,
  type Hub,
  type Route,
} from "../data";

interface FilterSidebarProps {
  hubs: Hub[];
  routes: Route[];
  visibleRoutes: Route[];
  hidden: Set<Filter>;
  onToggle: (filter: Filter) => void;
}

export function FilterSidebar({
  hubs,
  routes,
  visibleRoutes,
  hidden,
  onToggle,
}: FilterSidebarProps) {
  const totalShipments = visibleRoutes.reduce((s, r) => s + r.shipments, 0);
  const onTimeShipments = visibleRoutes
    .filter((r) => r.status === "active")
    .reduce((s, r) => s + r.shipments, 0);
  const delayedShipments = totalShipments - onTimeShipments;
  const onTimeRate = totalShipments
    ? Math.round((onTimeShipments / totalShipments) * 100)
    : 0;
  const activeCount = routes.filter((r) => r.status === "active").length;
  const delayedCount = routes.filter((r) => r.status === "delayed").length;
  const airRouteCount = routes.filter((r) => r.mode === "air").length;
  const groundRouteCount = routes.filter((r) => r.mode === "ground").length;

  return (
    <Sidebar collapsible="offcanvas">
      <SidebarHeader className="p-4">
        <div className="flex items-center gap-2">
          <div className="bg-sidebar-primary text-sidebar-primary-foreground flex aspect-square size-8 items-center justify-center rounded-lg">
            <Network className="size-4" />
          </div>
          <div className="flex flex-col gap-0.5 leading-none">
            <span className="text-sm font-medium">Logistics Network</span>
            <span className="text-muted-foreground text-xs">
              Domestic Routes
            </span>
          </div>
        </div>
      </SidebarHeader>

      <SidebarSeparator className="mx-0" />

      <SidebarContent>
        <SidebarGroup className="gap-3 px-4 pt-4 pb-2">
          <dl className="grid grid-cols-2 gap-4">
            <Stat label="Shipments" value={totalShipments.toLocaleString()} />
            <Stat label="On time" value={`${onTimeRate}%`} />
          </dl>
          <div className="flex h-1 gap-0.5">
            {(
              [
                ["active", onTimeShipments],
                ["delayed", delayedShipments],
              ] as const
            )
              .filter(([, value]) => value > 0)
              .map(([status, value]) => (
                <span
                  key={status}
                  className="rounded-full"
                  style={{
                    flexGrow: value,
                    backgroundColor: statusConfig[status].color,
                  }}
                />
              ))}
          </div>
        </SidebarGroup>

        <SidebarGroup>
          <SidebarGroupLabel>Transport Mode</SidebarGroupLabel>
          <SidebarGroupContent>
            <SidebarMenu>
              <FilterItem
                label="Air Freight"
                count={airRouteCount}
                hidden={hidden.has("air")}
                onToggle={() => onToggle("air")}
              >
                <Plane />
              </FilterItem>
              <FilterItem
                label="Ground"
                count={groundRouteCount}
                hidden={hidden.has("ground")}
                onToggle={() => onToggle("ground")}
              >
                <Truck />
              </FilterItem>
            </SidebarMenu>
          </SidebarGroupContent>
        </SidebarGroup>

        <SidebarGroup>
          <SidebarGroupLabel>Status</SidebarGroupLabel>
          <SidebarGroupContent>
            <SidebarMenu>
              {(["active", "delayed"] as const).map((status) => (
                <FilterItem
                  key={status}
                  label={statusConfig[status].label}
                  count={status === "active" ? activeCount : delayedCount}
                  hidden={hidden.has(status)}
                  onToggle={() => onToggle(status)}
                >
                  <span className="flex size-4 items-center justify-center">
                    <span
                      className="size-2 rounded-full"
                      style={{ backgroundColor: statusConfig[status].color }}
                    />
                  </span>
                </FilterItem>
              ))}
            </SidebarMenu>
          </SidebarGroupContent>
        </SidebarGroup>

        <SidebarGroup>
          <SidebarGroupLabel>Region</SidebarGroupLabel>
          <SidebarGroupContent>
            <SidebarMenu>
              {(["west", "midwest", "south", "northeast"] as const).map(
                (region) => (
                  <FilterItem
                    key={region}
                    label={regionLabels[region]}
                    count={hubs.filter((h) => h.region === region).length}
                    hidden={hidden.has(region)}
                    onToggle={() => onToggle(region)}
                  >
                    <MapPin />
                  </FilterItem>
                ),
              )}
            </SidebarMenu>
          </SidebarGroupContent>
        </SidebarGroup>
      </SidebarContent>
    </Sidebar>
  );
}

function Stat({ label, value }: { label: string; value: number | string }) {
  return (
    <div className="flex flex-col gap-1">
      <dt className="text-muted-foreground text-xs">{label}</dt>
      <dd className="text-lg font-medium tabular-nums">{value}</dd>
    </div>
  );
}

function FilterItem({
  label,
  count,
  hidden,
  onToggle,
  children,
}: {
  label: string;
  count: number;
  hidden: boolean;
  onToggle: () => void;
  children: React.ReactNode;
}) {
  return (
    <SidebarMenuItem
      className={cn("transition-opacity", hidden && "opacity-50")}
    >
      <SidebarMenuButton aria-pressed={!hidden} onClick={onToggle}>
        {children}
        <span>{label}</span>
      </SidebarMenuButton>
      <SidebarMenuBadge>{count}</SidebarMenuBadge>
    </SidebarMenuItem>
  );
}

"use client";

import { useMemo } from "react";
import {
  Map,
  MapArc,
  MapControls,
  MapMarker,
  MarkerContent,
  MarkerTooltip,
} from "@/components/ui/map";
import { SidebarTrigger } from "@/components/ui/sidebar";
import {
  modeConfig,
  networkBounds,
  regionLabels,
  statusConfig,
  type Hub,
  type Route,
} from "../data";
import { Separator } from "@/components/ui/separator";

interface NetworkMapProps {
  hubs: Hub[];
  routes: Route[];
}

function MapControlsCard() {
  return (
    <div className="border-border/40 bg-background/70 absolute top-4 left-4 z-20 flex items-center gap-3 rounded-lg border px-2.5 py-1.5 backdrop-blur-sm">
      <SidebarTrigger />
      <Separator orientation="vertical" className="h-4!" />
      <div className="flex items-center gap-3 text-xs">
        <div className="flex items-center gap-1.5">
          <span
            className="h-0.5 w-4 shrink-0 rounded-full"
            style={{ backgroundColor: modeConfig.air.color }}
          />
          <span>{modeConfig.air.label}</span>
        </div>
        <div className="flex items-center gap-1.5">
          <span
            className="h-0.5 w-4 shrink-0 rounded-full"
            style={{ backgroundColor: modeConfig.ground.color }}
          />
          <span>{modeConfig.ground.label}</span>
        </div>
        <div className="flex items-center gap-1.5">
          <span
            className="h-0.5 w-4 shrink-0 rounded-full"
            style={{ backgroundColor: statusConfig.delayed.color }}
          />
          <span>{statusConfig.delayed.label}</span>
        </div>
        <Separator orientation="vertical" className="h-4!" />
        <div className="flex items-center gap-1.5">
          <div className="size-2.5 shrink-0 rounded-full border border-white bg-blue-500 shadow-sm" />
          <span>Hub</span>
        </div>
      </div>
    </div>
  );
}

export function NetworkMap({ hubs, routes }: NetworkMapProps) {
  const arcs = useMemo(() => {
    const hubById: Record<string, Hub> = Object.fromEntries(
      hubs.map((hub) => [hub.id, hub]),
    );
    return routes.flatMap((route) => {
      const fromHub = hubById[route.from];
      const toHub = hubById[route.to];
      if (!fromHub || !toHub) return [];
      return [
        {
          id: `${route.from}-${route.to}`,
          from: [fromHub.lng, fromHub.lat] as [number, number],
          to: [toHub.lng, toHub.lat] as [number, number],
          color:
            route.status === "delayed"
              ? statusConfig.delayed.color
              : modeConfig[route.mode].color,
        },
      ];
    });
  }, [hubs, routes]);

  return (
    <div className="relative h-full">
      <MapControlsCard />

      <Map
        bounds={networkBounds}
        fitBoundsOptions={{
          padding: { top: 80, bottom: 40, left: 40, right: 40 },
        }}
        projection={{ type: "globe" }}
      >
        <MapControls />
        <MapArc
          data={arcs}
          curvature={0.3}
          paint={{
            "line-color": ["get", "color"],
            "line-width": 2,
            "line-opacity": 0.65,
          }}
          interactive={false}
        />

        {hubs.map((hub) => (
          <MapMarker key={hub.id} longitude={hub.lng} latitude={hub.lat}>
            <MarkerContent>
              <div className="size-3 rounded-full border-2 border-white bg-blue-500 shadow-md" />
            </MarkerContent>
            <MarkerTooltip
              offset={16}
              className="bg-background text-foreground border px-2.5 py-1.5"
            >
              <p className="font-medium">{hub.city}</p>
              <p className="text-muted-foreground mt-1">
                {hub.shipments.toLocaleString()} shipments
                <span className="mx-1">•</span>
                {regionLabels[hub.region]}
              </p>
            </MarkerTooltip>
          </MapMarker>
        ))}
      </Map>
    </div>
  );
}
